use super::*;
use semio_framework_os_kernel::sqlite_snapshot::artifact::NativeEncodingBound;
fn strings<'a>(b:&mut NativeEncodingBound<'_,'_>,values:impl IntoIterator<Item=&'a str>)->Result<(),ValueError>{for v in values{b.repeated(v.len(),16)?;}Ok(())}
fn dictionary(b:&mut NativeEncodingBound<'_,'_>,root:&Dictionary)->Result<(),ValueError>{let mut pending=vec![root];while let Some(d)=pending.pop(){b.check_rows(d.len())?;b.checkpoint()?;for(key,v)in d.iter(){strings(b,[key.as_str()])?;b.add(256)?;match v{NeuralValue::Dictionary(d)=>pending.push(d),NeuralValue::Atom(Atom::String(v))=>strings(b,[v.as_str()])?,NeuralValue::Atom(Atom::Decimal(_))=>b.add(2048)?,_=>b.add(128)?}}}Ok(())}
fn value(b:&mut NativeEncodingBound<'_,'_>,root:&DslValue)->Result<(),ValueError>{let mut pending=vec![root];while let Some(v)=pending.pop(){b.check_rows(pending.len()+1)?;b.add(128)?;match v{DslValue::Null|DslValue::Bool(_)=>{},DslValue::Number(_)=>b.add(2048)?,DslValue::String(v)=>strings(b,[v.as_str()])?,DslValue::Bytes(v)=>b.repeated(v.len(),8)?,DslValue::Array(values)=>{b.check_rows(values.len())?;for v in values{b.checkpoint()?;pending.push(v);}},DslValue::Object(values)=>{b.check_rows(values.len())?;for(k,v)in values{strings(b,[k.as_str()])?;pending.push(v);}}}}Ok(())}
fn tree(b:&mut NativeEncodingBound<'_,'_>,root:&Tree)->Result<(),ValueError>{let mut pending=vec![root];while let Some(t)=pending.pop(){b.check_rows(t.neurons.len().checked_add(t.synapses.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"procedural native graph count overflow"))?)?;b.checkpoint()?;for n in &t.neurons{strings(b,[n.id.as_str(),n.kind.as_str()])?;dictionary(b,&n.params)?;b.add(1024)?;if let Some(t)=&n.tree{pending.push(t);}}for s in &t.synapses{strings(b,[s.id.as_str(),s.from.as_str(),s.to.as_str(),s.from_port.as_str(),s.to_port.as_str()])?;b.add(1024)?;}}Ok(())}
fn gui(b:&mut NativeEncodingBound<'_,'_>,ui:&FlowUi)->Result<(),ValueError>{b.add(6144)?;b.check_rows(ui.nodes.len().checked_add(ui.previews.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"procedural native gui count overflow"))?)?;for(name,n)in ui.nodes.iter(){strings(b,[name.as_str()])?;b.add(4096)?;match &n.chrome{NodeChrome::Plain{..}=>b.add(128)?,NodeChrome::Slider{label,..}=>{strings(b,[label.as_str()])?;b.add(8192)?;},NodeChrome::Note{text}=>strings(b,[text.as_str()])?,NodeChrome::Image{src}=>strings(b,[src.as_str()])?,NodeChrome::Variable{name,schema}=>strings(b,[name.as_str(),schema.as_str()])?}}
 for p in &ui.previews{strings(b,[p.id.as_str(),p.mode.as_str()])?;if let Some(s)=&p.source{strings(b,[s.neuron.as_str(),s.channel.as_str()])?;}dictionary(b,&p.preview)?;b.check_rows(p.expanded.len())?;strings(b,p.expanded.iter().map(String::as_str))?;b.add(if p.layout.is_some(){4096}else{128})?;}Ok(())}
/// 📏️ Bounds every retained field before the owner starts its native Text or Binary codec.
pub fn preflight(host:&FlowHostSnapshot,generation:&GenerationPlayRoot,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut b=NativeEncodingBound::new(c)?;b.add(8192)?;strings(&mut b,[host.schema.as_str()])?;b.check_rows(host.widgets.len().checked_add(host.synapses.len()).and_then(|n|n.checked_add(host.layout.len())).and_then(|n|n.checked_add(generation.generations.len())).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"procedural native entity count overflow"))?)?;
 for w in &host.widgets{b.add(1024)?;match w{Widget::Neuron{id,neuron_kind,params,input_ports,output_ports,..}=>{strings(&mut b,[id.as_str(),neuron_kind.as_str()])?;dictionary(&mut b,params)?;b.check_rows(input_ports.len().checked_add(output_ports.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"procedural native port count overflow"))?)?;strings(&mut b,input_ports.iter().chain(output_ports).map(String::as_str))?;},Widget::InputSlider{id,label,..}=>{strings(&mut b,[id.as_str(),label.as_str()])?;b.add(8192)?;},Widget::InputNote{id,text}=>strings(&mut b,[id.as_str(),text.as_str()])?,Widget::InputImage{id,src}=>strings(&mut b,[id.as_str(),src.as_str()])?,Widget::Variable{id,name,schema}=>strings(&mut b,[id.as_str(),name.as_str(),schema.as_str()])?,Widget::OutputPreview{id,preview,expanded}=>{strings(&mut b,[id.as_str()])?;dictionary(&mut b,preview)?;b.check_rows(expanded.len())?;strings(&mut b,expanded.iter().map(String::as_str))?;},Widget::OutputAction{id,action}=>strings(&mut b,[id.as_str(),action.as_str()])?,Widget::OutputExport{id,format}=>strings(&mut b,[id.as_str(),format.as_str()])?,Widget::Cluster{id,name,tree:t,flow}=>{strings(&mut b,[id.as_str(),name.as_str()])?;tree(&mut b,t)?;gui(&mut b,flow)?;}}}
 for s in &host.synapses{strings(&mut b,[s.id.as_str(),s.from.as_str(),s.to.as_str(),s.from_port.as_str(),s.to_port.as_str()])?;b.add(1024)?;}for(name,_)in host.layout.iter(){strings(&mut b,[name.as_str()])?;b.add(4096)?;}if let Some(v)=&generation.selected_generation_id{strings(&mut b,[v.as_str()])?;}if let Some(v)=&generation.preview_text{strings(&mut b,[v.as_str()])?;}for g in &generation.generations{strings(&mut b,[g.id.as_str(),g.name.as_str()])?;b.add(1024)?;b.check_rows(g.values.len())?;for(k,v)in &g.values{strings(&mut b,[k.as_str()])?;value(&mut b,v)?;}}b.finish()}
